function initDownloadRegions() {
  loadStats().then(function (stats) {
    const el = $("#download-stats-region");
    if (el) el.value = JSON.stringify(stats, null, 2);
  });
  loadRecentTweaks().then(function (tweaks) {
    const el = $("#download-recent-tweaks-region");
    if (el) el.value = JSON.stringify(tweaks, null, 2);
  });
  loadWaketimeSchedule().then(function (schedule) {
    const el = $("#download-waketime-schedule-region");
    if (el) el.value = JSON.stringify(schedule, null, 2);
  });
  loadLog().then(function (log) {
    const csv = ["tickId,utcTime,filesChanged,checkStatus"].concat(
      log.map(function (t) {
        return [t.tickId, t.runAt, t.changedPaths, t.checkStatus].join(",");
      })
    ).join("\n");
    const el = $("#download-log-region");
    if (el) el.value = csv;
  });
}
```

